def words(t): return re.findall(r"[A-Za-z][A-Za-z']*", t)
def sents(t): return [s for s in re.split(r"(?<=[.?!])\s+", t.strip()) if s]
def grams(t,n):
    w=[x.lower() for x in words(t)]
    return {" ".join(w[i:i+n]) for i in range(len(w)-n+1)}
base=[k for k in T if k.startswith("B")]
# Phrases that occur in at least one baseline email (her vocabulary of word pairs and triples)
def familiar_rate(key, n):
    others=set().union(*[grams(T[k],n) for k in base if k!=key])
    g=grams(T[key],n)
    return len(g & others)/len(g) if g else 0
rows=[]
for k,t in T.items():
    w=words(t); s=sents(t)
    rows.append((k,len(w),round(len(w)/len(s),1),round(100*familiar_rate(k,2)),round(100*familiar_rate(k,3))))
print(f"{'email':26} {'words':>5} {'w/sent':>6} {'pairs seen in her other emails %':>34} {'triples %':>9}")
for r in rows: print(f"{r[0]:26} {r[1]:5} {r[2]:6} {r[3]:34} {r[4]:9}")
b2=[r[3] for r in rows if r[0].startswith('B')]; b3=[r[4] for r in rows if r[0].startswith('B')]
print(f"\nBaseline range (leave-one-out): pairs {min(b2)}–{max(b2)}% (median {st.median(b2)}), triples {min(b3)}–{max(b3)}% (median {st.median(b3)})")
# Sentence-level: which sentences of S1 are made of her phrasing?
allb=set().union(*[grams(T[k],3) for k in base])
for key in ["S1 2026-10-12b Registry","T2 2026-10-19 Cory"]:
    print(f"\n{key}, sentence by sentence (share of word triples found anywhere in her {len(base)} baseline emails):")
    for s in sents(T[key]):
        g=grams(s,3); r=round(100*len(g&allb)/len(g)) if g else 0
        print(f"  {r:3}%  {s}")
# Marker phrases: never seen in her baseline vs her habits
marks=["in lieu of","in the first instance","undertaking","in receipt of","better placed","believes","jointly","not contactable","set down","respectfully requests","consideration of this request","in relation to","i refer to the above matter","as soon as possible","in the hopes"]
later=[k for k in T if k[0] in "STL"]
print(f"\nPhrase -> how many of her {len(base)} baseline emails use it; and which later or other texts use it")
for m in marks:
    nb=sum(1 for k in base if m in T[k].lower()); used=[k.split()[0] for k in later if m in T[k].lower()]
    print(f"  {m:30} baseline {nb:2}/{len(base)} | used in: {', '.join(used) or '-'}")
